27	            @NotBlank(message = "requestId 不能为空") String requestId,
28	            @NotBlank(message = "bagTag 不能为空") String bagTag,
29	            @NotNull(message = "legIds 不能为空")
30	            @Size(min = 1, max = 5, message = "行程航段数必须为 1~5") List<@NotBlank(message = "航段不能为空") String> legIds) {
31	    }
