36	            @NotNull(message = "expectedVersion 不能为空") Integer expectedVersion,
37	            @NotNull(message = "bagTags 不能为空")
38	            @Size(min = 1, max = 20, message = "批量装载数量必须为 1~20") List<@NotBlank(message = "bagTag 不能为空") String> bagTags) {
39	    }
