                misloadBag("BAG1", 3, "SHA"),
                misloadBag("BAG2", 3, "SHA"))).andExpect(status().isCreated());
        registerMisload("INC1", "LEG_M", List.of(
                misloadBag("BAG1", 4, "SHA"),
                misloadBag("BAG2", 4, "SHA"))).andExpect(status().isConflict());
    }

    @Test
    void register_rejectsDeliveredInTransitAndOpenIncidentBags() throws Exception {
        registerLeg("LEG_O1", "PEK", "SHA", null);
        registerLeg("LEG_M", "PEK", "SHA", "2026-09-22T06:00:00Z");
        registerBag("BAG_D", List.of("LEG_O1"));
        registerBag("BAG_L", List.of("LEG_O1"));
        registerBag("BAG3", List.of("LEG_O1"));
        // BAG_D 已交付
        loadSealArrive("LEG_O1", 1, List.of("BAG_D", "BAG_L", "BAG3"));
        // BAG_L 已在途（再注册一段行程使其停在 SHA，然后装到后续航段上）
        registerLeg("LEG_O2", "SHA", "CAN", null);
        registerLeg("LEG_M2", "CTU", "SHA", "2026-09-22T07:00:00Z");
        // BAG_L 与 BAG3 只有 LEG_O1 行程，已随 LEG_O1 到达 SHA 且交付；改造成：重新准备在途行李
        registerLeg("LEG_F", "SHA", "CAN", null);
        // 已交付行李不能登记错装 -> 409
        registerMisload("INC_D", "LEG_M", List.of(
                misloadBag("BAG_D", 3, "SHA"),
                misloadBag("BAG3", 3, "SHA"))).andExpect(status().isConflict());

        // 在途行李：两件含两段行程的行李到达 SHA 后，一件装载到 LEG_F
        registerBag("BAG_A", List.of("LEG_O1", "LEG_O2"));
        registerBag("BAG_B", List.of("LEG_O1", "LEG_O2"));
        // LEG_O1 已 ARRIVED，不能再装载；让两件行李改走新的航段链
        registerLeg("LEG_N1", "PEK", "SHA", null);
        registerLeg("LEG_N2", "SHA", "CAN", null);
        registerBag("BAG_A2", List.of("LEG_N1", "LEG_N2"));
        registerBag("BAG_B2", List.of("LEG_N1", "LEG_N2"));
        loadSealArrive("LEG_N1", 1, List.of("BAG_A2", "BAG_B2"));
        load("LEG_N2", 2, List.of("BAG_A2")).andExpect(status().isOk());

        // BAG_A2 已在途 -> 整单 422
        registerMisload("INC_T", "LEG_M2", List.of(
                misloadBag("BAG_A2", 4, "SHA"),
                misloadBag("BAG_B2", 3, "SHA"))).andExpect(status().isUnprocessableEntity());

        // 正常登记 BAG_B2 后，再次以同件行李登记别的未结事件 -> 409
        registerMisload("INC_OPEN", "LEG_M2", List.of(
                misloadBag("BAG_B2", 3, "SHA"),
                misloadBag("BAG3", 3, "SHA"))).andExpect(status().isCreated());
        registerMisload("INC_AGAIN", "LEG_M2", List.of(
                misloadBag("BAG_B2", 4, "SHA"),
                misloadBag("BAG_D", 3, "SHA"))).andExpect(status().isConflict());
    }

